"use client";

import { useDeferredValue, useEffect, useState } from "react";
import { Sparkline } from "@/components/charts";
import { apiGet } from "@/lib/api";
import { formatMonth, formatNumber } from "@/lib/format";
import type { Branch, ItemRow, Variant } from "@/lib/types";

type Props = { branches: Branch[]; branchCode: string; onBranchChange: (value: string) => void };

export function ItemsModule({ branches, branchCode, onBranchChange }: Props) {
  const [query, setQuery] = useState("");
  const deferredQuery = useDeferredValue(query);
  const [status, setStatus] = useState("all");
  const [data, setData] = useState<{ items: ItemRow[]; total: number; data_as_of_month: string } | null>(null);
  const [selected, setSelected] = useState<ItemRow | null>(null);
  const [variants, setVariants] = useState<Variant[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    apiGet<{ items: ItemRow[]; total: number; data_as_of_month: string }>("/items", {
      q: deferredQuery,
      branch_code: branchCode,
      status,
      page_size: 50,
    })
      .then((response) => {
        if (!cancelled) {
          setData(response);
          setError(null);
        }
      })
      .catch((reason: Error) => {
        if (!cancelled) setError(reason.message);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [branchCode, deferredQuery, status]);

  function openVariants(item: ItemRow) {
    setSelected(item);
    apiGet<{ items: Variant[] }>(`/items/${encodeURIComponent(item.base_sku)}/variants`)
      .then((response) => setVariants(response.items))
      .catch((reason: Error) => setError(reason.message));
  }

  const months = data?.items[0]?.trend.map((point) => point.month) ?? [];

  return (
    <section className="module">
      <div className="module-heading">
        <div><p className="eyebrow">MODULE 01</p><h2>Danh mục và lịch sử SKU</h2></div>
        <div className="result-count">{formatNumber(data?.total)} SKU phù hợp</div>
      </div>
      <div className="filters">
        <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Tìm SKU hoặc tên sản phẩm..." aria-label="Tìm SKU" />
        <select value={branchCode} onChange={(event) => onBranchChange(event.target.value)}>
          <option value="__ALL__">Tất cả chi nhánh</option>
          {branches.map((branch) => <option key={branch.branch_code} value={branch.branch_code}>{branch.branch_code} · {branch.branch_name}</option>)}
        </select>
        <select value={status} onChange={(event) => setStatus(event.target.value)}>
          <option value="all">Tất cả trạng thái</option><option value="active">Đang hoạt động</option><option value="inactive">Vô hiệu hóa</option>
        </select>
        <button className="secondary" onClick={() => { setQuery(""); setStatus("all"); onBranchChange("__ALL__"); }}>Đặt lại</button>
      </div>
      {error ? <div className="error-banner">{error}</div> : null}
      <div className="table-card">
        <div className="table-scroll">
          <table className="data-table sku-table">
            <thead><tr><th>Trạng thái</th><th>Mã SKU · Tên sản phẩm</th><th>Quy cách</th><th>Đuôi màu</th><th>Xu hướng TT 12 tháng</th>{months.map((month) => <th key={month}>{formatMonth(month)}<small>M2 bán ra</small></th>)}</tr></thead>
            <tbody>
              {loading ? <tr><td colSpan={17} className="empty">Đang tải dữ liệu thật từ Supabase…</td></tr> : null}
              {!loading && !data?.items.length ? <tr><td colSpan={17} className="empty">Không có SKU theo bộ lọc hiện tại.</td></tr> : null}
              {data?.items.map((item) => (
                <tr key={item.base_sku} onClick={() => openVariants(item)} className={selected?.base_sku === item.base_sku ? "selected" : ""}>
                  <td><span className={`status-badge ${item.status}`}>{item.status === "active" ? "Đang hoạt động" : "Vô hiệu hóa"}</span></td>
                  <td className="item-cell"><strong className={item.status === "inactive" ? "inactive-name" : ""}>{item.base_sku}</strong><span className={item.status === "inactive" ? "inactive-name" : ""}>{item.sku_name ?? "Chưa có tên"}</span></td>
                  <td>{item.size_code}</td>
                  <td><strong>{item.variant_count}</strong><small>{item.active_variant_count} hoạt động</small></td>
                  <td><Sparkline values={item.trend.map((point) => point.value)} /></td>
                  {item.trend.map((point) => <td key={point.month} className="number-cell">{formatNumber(point.value)}</td>)}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {selected ? (
        <aside className="detail-panel">
          <div className="detail-title"><div><p className="eyebrow">SKU ĐANG CHỌN</p><h3>{selected.base_sku}</h3><p>{selected.sku_name}</p></div><button className="icon-button" onClick={() => setSelected(null)}>Đóng</button></div>
          <div className="variant-grid">
            {variants.map((variant) => (
              <article key={variant.bravo_sku} className="variant-card">
                <span className={`status-dot ${variant.status}`} />
                <div><strong>{variant.bravo_sku}</strong><p>Group 5: {variant.has_color_suffix ? variant.color_suffix : "Không có đuôi màu"}</p><small>Bán dương cuối: {variant.last_positive_sale_month ? formatMonth(variant.last_positive_sale_month) : "—"}</small></div>
                <span className={`status-text ${variant.status}`}>{variant.status === "active" ? "Hoạt động" : "Vô hiệu hóa"}</span>
              </article>
            ))}
          </div>
        </aside>
      ) : null}
    </section>
  );
}
